actions.script:
const enc = text => String(text ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
const L = text => enc(ec.l10n.localize(text))
printUrl = '/apps/People/Employees/BadgePrint?renderMode=html-print&kioskBadgeId=' + encodeURIComponent(kioskBadgeId || '')
printHtml = ''
if (['html-print', 'html'].includes(sri.getRenderMode())) {
    let printed = null
    let refusal = ''
    ec.message.pushErrors()
    try {
        printed = ec.service.sync().name('mantle.humanres.AttendanceServices.print#KioskBadge')
            .parameters({kioskBadgeId: kioskBadgeId || ''}).requireNewTransaction(true).call() || null
        if (ec.message.hasError()) refusal = ec.message.getErrorsString()
    } catch (error) {
        refusal = String(error.message || error)
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
    // a refusal says why (printed already, too late, not the issuer, not available) in its own words, without its code
    const reason = /\b[A-Z][A-Z0-9_]{3,}:\s*([^\n]*)/.exec(refusal)
    printHtml = printed && !refusal
        ? '<div style="width:85.6mm;min-height:54mm;box-sizing:border-box;border:1px solid #999;border-radius:3mm;padding:4mm;' +
            'font-family:sans-serif;display:flex;flex-direction:column;justify-content:space-between">' +
            '<div style="font-size:9pt;color:#555">' + enc(printed.organizationName) + ' · ' + L('Clocking badge') + '</div>' +
            '<div style="font-size:14pt;font-weight:bold">' + enc(printed.personName) + '</div>' +
            '<div>' + printed.barcodeSvg + '</div>' +
            '<div style="font-size:10pt;letter-spacing:1px">' + enc(printed.numberText) + '</div>' +
            '<div style="font-size:7pt;color:#777">' + L('Issued') + ' ' + enc(printed.issuedDateText) + ' · ' +
            L('Keep your PIN to yourself. If this badge is lost, ask HR to revoke it.') + '</div></div>'
        : '<p>' + (reason ? enc(ec.l10n.localize(reason[1])) : L('This badge is not available')) + '</p>'
}
